//! Raw bindings to libghostty-vt, built from Ghostty at [`GHOSTTY_COMMIT`] with Zig 0.16.
//!
//! `src/bindings.rs` is generated by `scripts/gen-bindings.sh` and checked in; `build.rs` only
//! builds and links the static library (see README.md for the offline build). Only `temor-vt`
//! uses this crate.
#![allow(unsafe_code)]
#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals)]
#![allow(missing_debug_implementations)]
#![allow(clippy::all)]
#![allow(rustdoc::all)]

#[rustfmt::skip]
mod bindings;

pub use bindings::*;

/// The Ghostty commit the bindings and the linked library come from.
pub const GHOSTTY_COMMIT: &str = "7ec9e26a29399b30ef78f06985fc75045b3cecb6";

/// A zeroed C "sized" struct with its `size` field set, as the C API's `GHOSTTY_INIT_SIZED`.
#[macro_export]
macro_rules! sized {
    ($ty:ty) => {{
        let mut t = <$ty as ::std::default::Default>::default();
        t.size = ::std::mem::size_of::<$ty>();
        t
    }};
}
